// Shared highlight colors for the MSA/tree hover and selection overlay canvases.
// Kept in one place so the reference-row color (drawn identically over both the
// tree and the alignment) can't drift between the two surfaces.

// reference (relativeTo) row, drawn over both the tree and the alignment
export const referenceColor = 'rgba(0,128,255,0.3)'

// tree-node descendant rows highlighted on hover. The alpha differs by surface
// intentionally: the tree background is plain so it can take a stronger wash,
// while the alignment cells are already colored so a lighter wash reads better.
export const treeHoverColor = 'rgba(255,165,0,0.2)'
export const multiRowHoverColor = 'rgba(255,165,0,0.15)'

// the hovered column/row, and the one pinned by a click. Drawn on the alignment
// overlay canvas and again as plain divs over the track area, which have to
// match or the crosshair appears to change color as it crosses the tracks.
export const hoverColor = 'rgba(0,0,0,0.15)'
export const clickColor = 'rgba(128,128,0,0.2)'

// the selected block, a blue that reads apart from the orange highlights
export const selectionFill = 'rgba(25,118,210,0.22)'
export const selectionBorder = 'rgba(25,118,210,0.95)'

// the band of the highlight whose bracket the pointer is over; neutral, so it
// reads apart from both the highlight's own color and the selection's blue
export const highlightHoverWash = 'rgba(0,0,0,0.08)'
